import { chromium, firefox, webkit } from '@playwright/test';
import assert from 'node:assert/strict';
import { mkdir, writeFile } from 'node:fs/promises';
import path from 'node:path';
// Component callback atomicity is covered here; native commits are tested separately.
const engine=process.env.RB03_ENGINE ?? 'chromium', launcher={chromium,firefox,webkit}[engine];
if(!launcher) throw new Error(`Unknown engine: ${engine}`);
const output=process.env.RB03_OUTPUT_DIR ?? 'test-results/rb03-components';
await mkdir(output,{recursive:true});
const browser = await launcher.launch(engine === 'chromium' && process.env.RB03_CHROMIUM_PATH ? {executablePath:process.env.RB03_CHROMIUM_PATH,args:['--no-sandbox']} : {});
const page = await browser.newPage({viewport:{width:390,height:900}});
const errors=[];page.on('pageerror',error=>{errors.push(error.message);console.log('Browser error',error.message);});
await page.goto(process.env.RB03_DEV_URL ?? 'http://127.0.0.1:5213/shinariokanri/');
await page.evaluate(async()=>{
 const source=await(await fetch('/shinariokanri/src/ui/Timeline.tsx')).text();
 const main=await(await fetch('/shinariokanri/src/main.tsx')).text();
 const reactURL=source.match(/from ["']([^"']*\/react\.js\?v=[a-f0-9]+)["']/)[1], rootURL=main.match(/from ["']([^"']*\/react-dom_client\.js\?v=[a-f0-9]+)["']/)[1];
 const {default:React}=await import(reactURL);
 const {default:{createRoot}}=await import(rootURL);
 const {Timeline}=await import('/shinariokanri/src/ui/Timeline.tsx');
 const {createProject,createEntity,emptyValidity,validateProject}=await import('/shinariokanri/src/domain/model.ts');
 const project=createProject('年表局所確認');
 const person=createEntity(project.projectId,'character','アオ');
 const g1=createEntity(project.projectId,'group','街の仲間',{members:[person.id]});
 const g2=createEntity(project.projectId,'group','記録係',{members:[person.id]});
 const a=createEntity(project.projectId,'event','A開始',{time:{mode:'interval',start:'0',end:'100',calendarId:project.calendarId},laneRole:'both',participants:[{characterId:person.id,role:'actor'}]});
 const b=createEntity(project.projectId,'event','B開始',{time:{mode:'instant',at:'200',calendarId:project.calendarId},laneRole:'participants',participants:[{characterId:person.id,role:'witness'}]});
 a.data.constraints=[{type:'end_gap',targetEventId:b.id,minimumTicks:'50',maximumTicks:'100'}];
 project.entities=[person,g1,g2,a,b];
 const overlaps=Array.from({length:250},(_,i)=>{const e=createEntity(project.projectId,'event',`重なり${i}`,{time:{mode:'instant',at:'0',calendarId:project.calendarId}});e.id=`20000000-0000-4000-8000-${i.toString(16).padStart(12,'0')}`;return e;});project.entities.push(...overlaps);
 project.relations=[{id:crypto.randomUUID(),projectId:project.projectId,revision:'0',fromId:a.id,toId:b.id,relationType:'causes',direction:'forward',validity:emptyValidity(),evidenceIds:[person.id],status:'provisional',visibility:'private'}];
 window.rb03Ids={a:a.id,b:b.id,person:person.id,relation:project.relations[0].id,last:overlaps[249].id};
 const host=document.createElement('div');document.body.replaceChildren(host);
 const root=createRoot(host);
 function Harness(){const[p,setProject]=React.useState(project),[selected,setSelected]=React.useState(null);window.rb03Project=p;
  return React.createElement(Timeline,{project:p,selectedId:selected,onSelect:setSelected,onAdd:()=>{},onSaveProject:async candidate=>{const valid=validateProject(candidate);if(!valid.ok)throw new Error(valid.issues.map(i=>i.message).join(' '));const saved={...candidate,revision:String(BigInt(p.revision)+1n)};setProject(saved);return saved;}});
 }root.render(React.createElement(Harness));
});
await page.getByRole('button',{name:'全体へ戻る',exact:true}).click();
const ids=await page.evaluate(()=>window.rb03Ids);
const canvas=page.locator('.timeline-canvas');
await canvas.evaluate(node=>{node.scrollTop=15000;node.scrollLeft=500;});
await page.locator(`[data-event-id="${ids.last}"]`).waitFor({state:'attached'});
const fixed=await page.locator('.timeline-axis .lane-label').boundingBox();const bounds=await canvas.boundingBox();assert.ok(Math.abs(fixed.x-bounds.x)<3,'axis label remains at canvas left after horizontal scroll');
await page.getByRole('button',{name:'出来事一覧',exact:true}).click();
await page.getByLabel('出来事一覧を検索').fill('A開始');
await page.locator('.event-table-row').click();
await page.getByRole('button',{name:'選択した出来事の日時・制約',exact:true}).click();
const dialog=page.getByRole('dialog');
await dialog.getByLabel('終了の世界内tick',{exact:true}).fill('180');
await dialog.getByRole('button',{name:'変更前の影響を確認',exact:true}).click();
assert.equal(await dialog.getByRole('button',{name:'差分を一括確定'}).isDisabled(),true,'fixed dependent cannot move implicitly');
await dialog.getByLabel('日時変更の連動先の扱い').selectOption('move');
await dialog.getByLabel('この日時の連動移動を承認する').check();
await dialog.getByRole('button',{name:'差分を一括確定'}).click();
await page.waitForTimeout(80);
assert.equal(await page.evaluate(id=>window.rb03Project.entities.find(e=>e.id===id).data.time.at,ids.b),'230');
await page.getByRole('button',{name:'前回の日時変更を一括取消'}).click();
await page.waitForTimeout(80);
assert.equal(await page.evaluate(id=>window.rb03Project.entities.find(e=>e.id===id).data.time.at,ids.b),'200');
await page.locator(`button[data-relation-id="${ids.relation}"]`).click();
await page.getByRole('dialog').getByLabel('年表の関係の種類').selectOption('requires');
await page.getByRole('dialog').getByRole('button',{name:'関係を保存',exact:true}).click();
await page.waitForTimeout(80);
assert.equal(await page.evaluate(id=>window.rb03Project.relations.find(r=>r.id===id).relationType,ids.relation),'requires');
await page.getByRole('button',{name:'グループ・人物レーン',exact:true}).click();
await page.getByRole('dialog').getByRole('button',{name:'街の仲間を後へ',exact:true}).click();
await page.waitForTimeout(80);
const groupOrder=await page.evaluate(()=>window.rb03Project.entities.filter(e=>e.kind==='group').map(e=>e.name));assert.deepEqual(groupOrder,['記録係','街の仲間']);
await page.getByRole('dialog').getByRole('button',{name:'閉じる',exact:true}).click();
await page.getByRole('button',{name:'年表',exact:true}).click();
await page.getByRole('button',{name:'選択対象へ',exact:true}).click();
await page.waitForTimeout(80);
assert.equal(await page.locator('.timeline-event.selected').count()>0,true);
for(const width of[320,390,768,1024]){await page.setViewportSize({width,height:900});await page.waitForTimeout(60);assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=window.innerWidth+1),`page remains within ${width}px`);}
assert.deepEqual(errors,[]);
await page.screenshot({path:path.join(output, `timeline-${engine}.png`),fullPage:true});
await writeFile(path.join(output, `timeline-${engine}.json`),JSON.stringify({engine,time:new Date().toISOString(),widths:[320,390,768,1024],checks:['overlap 250 beyond old cap','sticky label after horizontal scroll','fixed collision blocked','approved atomic movement','atomic undo','same relation ID editing','group tap reorder','selected target reveal','no page overflow','no page errors'],errors},null,2));
await browser.close();console.log(`RB03 ${engine} timeline smoke passed`);
